const kindle = {
  layout:'reflowable_or_fixed',
  trimSize:'Kein festes Papierformat bei reflowable eBooks',
  cover:{preferredPx:[1600,2560],minimumPx:[625,1000],maximumPx:[10000,10000],ratio:'1:1.6',format:['JPEG','TIFF'],colorProfile:'RGB',recommendedPpi:300}
};

function gutterMm(pages) {
  if (pages <= 150) return 9.6;
  if (pages <= 300) return 12.7;
  if (pages <= 500) return 15.9;
  if (pages <= 700) return 19.1;
  return 22.3;
}

const isColoring = /(malbuch|ausmal|coloring|aktivitätsbuch|activity book)/.test(auftrag);
const isChildren = /(kinder|kindergarten|vorschule|bis zu 6|3.?6 jahre|4.?6 jahre)/.test(auftrag);
const isWorkbook = /(arbeitsbuch|workbook|tagebuch|journal|notizbuch|übungsbuch)/.test(auftrag);
const isCookbook = /(kochbuch|rezepte|cookbook)/.test(auftrag);
const isNovel = /(roman|thriller|krimi|fantasy|liebesgeschichte|novel)/.test(auftrag);

let selectedId = String(s.kdp_format_wunsch || 'AUTO');
if (s.kdp_format_automatisch !== false || selectedId === 'AUTO') {
  if (isColoring || isChildren || isWorkbook) selectedId = '8.5x11';
  else if (isCookbook) selectedId = '8x10';
  else if (isNovel) selectedId = '5.5x8.5';
  else selectedId = '6x9';
}

let binding = String(s.kdp_bindung_wunsch || 'AUTO').toUpperCase();
if (binding === 'AUTO') binding = 'TASCHENBUCH';

let selected;
if (binding === 'HARDCOVER') {
  selected = hardcover.find(x => x.id.replace('HC_','') === selectedId) || hardcover.find(x => x.id === 'HC_6x9');
} else {
  selected = paperbackGlobal.find(x => x.id === selectedId) || paperbackGlobal.find(x => x.id === '6x9');
  binding = 'TASCHENBUCH';
}

let printType = String(s.kdp_druck_wunsch || 'AUTO').toUpperCase();
if (printType === 'AUTO') printType = (isColoring ? 'SCHWARZWEISS_WEISS' : (isChildren || isCookbook ? 'PREMIUMFARBE_WEISS' : 'SCHWARZWEISS_CREME'));

let bleed = String(s.kdp_beschnitt_wunsch || 'AUTO').toUpperCase();
if (bleed === 'AUTO') bleed = (isChildren || isColoring || isCookbook) ? 'MIT_BESCHNITT' : 'OHNE_BESCHNITT';

const pages = Math.max(24, Number(s.kdp_seiten_schaetzung || 100));
const trimW = selected.inch[0];
const trimH = selected.inch[1];
const interiorPdf = bleed === 'MIT_BESCHNITT'
  ? {widthIn:Number((trimW + 0.125).toFixed(3)), heightIn:Number((trimH + 0.25).toFixed(3)), note:'3,2 mm oben, unten und außen; kein Beschnitt an der Bindekante'}
  : {widthIn:trimW, heightIn:trimH};

const margins = {
  insideGutterMm:gutterMm(pages),
  outsideNoBleedMm:6.4,
  outsideWithBleedMm:9.6,
  recommendedSafeMm:12.7
};

const catalog = {
  sourceVersion:'KDP-Spezifikationen, gespeichert 2026-07-23',
  paperbackGlobal,
  paperbackJapan,
  hardcover,
  customPaperback:{widthIn:[4,8.5],heightIn:[6,11.69]},
  kindle,
  universal:{
    interiorImagesMinDpi:300,
    interiorFontMinPt:7,
    coverBleedMm:3.2,
    coverSafeDistanceFromOuterEdgeMm:6.4,
    coverFormula:'Breite = 2×Schnittbreite + Rückenbreite + 2×3,2 mm; Höhe = Schnitthöhe + 2×3,2 mm',
    spineBwWhiteMmPerPage:0.0572,
    spineBwCreamMmPerPage:0.0635,
    note:'Endgültige Covermaße immer nach finaler Seitenzahl mit dem offiziellen KDP-Coverrechner bestätigen.'
  }
};

return [{
  json:{
    ...s,
    kdp_catalog:catalog,
    kdp_selected:{
      binding,
      formatId:selected.id,
      trimIn:selected.inch,
      trimMm:selected.mm,
      printType,
      bleed,
      estimatedPages:pages,
      interiorPdf,
      margins,
      ebookCover:kindle.cover
    }
  }
}];

const s = $('00 – EINSTELLUNGEN').first().json;
const auftrag = String(s.buchauftrag || '').trim();
if (!auftrag) throw new Error('Kein Buchauftrag vorhanden.');

const modus = String(s.qualitaetsmodus || 'hoch').toLowerCase();
const schnell = s.schnellmodus === true;
let maxTok = Number(s.max_tokens_recherche) || 11000;
if (schnell) maxTok = Math.min(maxTok, 7000);
if (modus === 'maximal') maxTok = Math.max(maxTok, 14000);

const qualityExtra = modus === 'standard' ? '' : `
QUALITÄTSANFORDERUNGEN (erhöht):
- Jede wichtige Zahlenangabe oder Studie braucht eine nachvollziehbare Quelle oder wird als ungesichert markiert.
- Formuliere riskante oder medizinisch/rechtlich/finanzielle Aussagen ausdrücklich vorsichtig.
- Keine absoluten Heilsversprechen oder Garantien.
- Bevorzuge aktuelle und seriöse Quellen.`;

const prompt = `Du bist unabhängiger Rechercheanalyst und Faktenprüfer für ein deutschsprachiges Sachbuch.

AUFGABE:
1. Analysiere den Buchauftrag gründlich und quellenbasiert.
2. Nutze Google Search für aktuelle Belege, wo sinnvoll.
3. Trenne strikt:
   - VERIFIZIERTE FAKTEN (mit Quelle/URL)
   - PLAUSIBLE ANNAHMEN
   - WIDERSPRÜCHE
   - OFFENE FRAGEN
   - RISKANTE AUSSAGEN (dürfen nicht als sichere Tatsache erscheinen)
4. Erstelle eine klare, strukturierte Wissensbasis für den späteren Autor.
5. Erfinde niemals Quellen, Zahlen, Studien oder Zitate.
6. Markiere Unsicherheit ausdrücklich.

Beende die Antwort zwingend mit diesen Abschnitten:
QUELLENBASIS
WIDERSPRÜCHE
OFFENE FRAGEN
FAKTEN-CHECKLISTE
SICHERE SCHREIBREGELN
${qualityExtra}

BUCHAUFTRAG:
${auftrag}

Zielumfang: ${s.zielumfang || 'ca. 12000 Wörter'}
Sprache: ${s.sprache || 'Deutsch'}`;

return [{
  json: {
    requestBody: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      tools: s.quellenanalyse_aktiv !== false ? [{ google_search: {} }] : [],
      generationConfig: {
        maxOutputTokens: maxTok,
        temperature: modus === 'maximal' ? 0.25 : 0.3
      }
    },
    schnellmodus: schnell,
    qualitaetsmodus: modus
  }
}];

const s = $('00 – EINSTELLUNGEN').first().json;
const parts = $json?.candidates?.[0]?.content?.parts;
const text = Array.isArray(parts) ? parts.map(p => p.text || '').join('').trim() : '';
const meta = $json?.candidates?.[0]?.groundingMetadata || {};
const chunks = Array.isArray(meta.groundingChunks) ? meta.groundingChunks : [];
const sources = [];
const seen = new Set();
for (const c of chunks) {
  const w = c?.web;
  if (w?.uri && !seen.has(w.uri)) {
    seen.add(w.uri);
    sources.push({ title: (w.title || '').slice(0, 120), uri: w.uri });
  }
}
const valid = text.length > 200;
const appendix = sources.length
  ? '\n\nVERWENDETE QUELLEN:\n' + sources.map((s, i) => `${i + 1}. ${s.title} – ${s.uri}`).join('\n')
  : '';
const response = valid
  ? (text + appendix).slice(0, 18000)   // hard cap for downstream memory
  : `NOTFALL-RECHERCHE:\n${String(s.buchauftrag || '').slice(0, 4000)}`;

return [{
  json: {
    ok: true,
    response,
    notebookAnalyseStatus: valid ? 'Quellenanalyse mit Google Search übernommen' : 'Fallback – Auftrag als Basis',
    sources: sources.slice(0, 25),
    groundingQueries: (meta.webSearchQueries || []).slice(0, 10),
    provider: valid ? 'Gemini-Flash+Grounding' : 'Notfall'
  }
}];

const s = $('00 – EINSTELLUNGEN').first().json;
const research = String($('01B – RECHERCHE PRÜFEN').first().json.response || '').slice(0, 11000);
const modus = String(s.qualitaetsmodus || 'hoch').toLowerCase();
const schnell = s.schnellmodus === true;
let maxTok = Number(s.max_tokens_manuskript) || 30000;
if (schnell) maxTok = Math.min(maxTok, 18000);

const qualityBlock = {
  standard: `- Klare Kapitelstruktur
- Keine erfundenen Fakten
- Sparsame Verwendung von [FAKT PRÜFEN]`,
  hoch: `- Feste Struktur: Titel, kurze Einleitung, 6–12 Kapitel, klares Fazit/Schluss
- Einheitliche Perspektive und einheitliches Tempus
- Keine Meta-Floskeln („In diesem Kapitel…“, „Wie wir sehen werden…“)
- Kurze, klare Sätze und gut lesbare Absätze
- Keine erfundenen Quellen, Zahlen oder Studien
- [FAKT PRÜFEN] nur bei wirklich offenen Punkten
- Fachbegriffe bei erster Nennung verständlich einführen`,
  maximal: `- Feste Struktur: Titel, Einleitung, 8–14 Kapitel, Fazit, optional kurzer Ausblick
- Strikt einheitliche Perspektive und Tempus
- Hohe stilistische Konsistenz (Anrede, Begriffswahl, Ton)
- Keine Floskeln, keine Füllsätze, keine Wiederholungen
- Keine erfundenen Fakten; Unsicherheiten klar kennzeichnen
- [FAKT PRÜFEN] nur wenn unvermeidbar
- Besonders sorgfältige Formulierung bei medizinischen, rechtlichen oder finanziellen Themen
- Gute Lesbarkeit und professioneller Sachbuch-Ton`
}[modus] || '';

const prompt = `Du bist ein professioneller deutschsprachiger Sachbuch-Autor mit Lektoratsanspruch.

Schreibe ein vollständiges, veröffentlichungsreifes Manuskript.

PFLICHTREGELN:
- Sprache: ${s.sprache || 'Deutsch'}
- Zielumfang: ${s.zielumfang || 'ca. 12000 Wörter'}
- Nur Überschriften mit # und ##, sonst kein Markdown
- Kein Meta-Kommentar, direkter Beginn mit dem Buchtitel
${qualityBlock}

BUCHAUFTRAG:
${s.buchauftrag}

RECHERCHE / QUELLENBASIS:
${research}`;

return [{
  json: {
    requestBody: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: {
        maxOutputTokens: maxTok,
        temperature: modus === 'maximal' ? 0.45 : 0.55
      }
    },
    qualitaetsmodus: modus
  }
}];

const asText = (v) => {
  if (typeof v === 'string') return v.trim();
  if (Array.isArray(v)) return v.map(asText).filter(Boolean).join('\n').trim();
  if (v && typeof v === 'object') return asText(v.text ?? v.content ?? v.output_text ?? '');
  return '';
};
const raw = asText($json?.candidates?.[0]?.content?.parts) || asText($json?.response) || '';
const clean = raw.replace(/^\s*```(?:markdown|text)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
const ok = clean.length >= 1500;
return [{ json: { ok, response: clean, manuscriptFallbackUsed: false, charCount: clean.length } }];

const s = $('00 – EINSTELLUNGEN').first().json;
const research = String($('01B – RECHERCHE PRÜFEN').first().json.response || '').slice(0, 7000);
const prompt = `Schreibe ein vollständiges deutschsprachiges Sachbuch-Manuskript.
Zielumfang: ${s.zielumfang || 'ca. 10000 Wörter'}.
Keine erfundenen Fakten. Direkter Beginn mit Titel.

AUFTRAG:
${s.buchauftrag}

RECHERCHE:
${research}`;
return [{
  json: {
    requestBody: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: { maxOutputTokens: 18000, temperature: 0.5 }
    }
  }
}];

const asText = (v) => {
  if (typeof v === 'string') return v.trim();
  if (Array.isArray(v)) return v.map(asText).filter(Boolean).join('\n').trim();
  if (v && typeof v === 'object') return asText(v.text ?? v.content ?? '');
  return '';
};
let text = asText($json?.candidates?.[0]?.content?.parts) || '';
text = text.replace(/^\s*```(?:markdown|text)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
if (text.length < 800) {
  const s = $('00 – EINSTELLUNGEN').first().json;
  text = `TECHNISCHE NOTFALL-ZWISCHENFASSUNG\n\nTitel: ${String(s.buchauftrag||'').slice(0,80)}\nAutor: ${s.autorenname}\n\n${String(s.buchauftrag||'')}\n\n(Beide Schreibmodelle ohne verwertbares Ergebnis.)`;
}
return [{ json: { ok: true, response: text, manuscriptFallbackUsed: true, charCount: text.length } }];

const s = $('00 – EINSTELLUNGEN').first().json;
let ms = '';
try {
  const a = $('02B – MANUSKRIPT NORMALISIEREN').first().json;
  if (a?.ok && a.response) ms = a.response;
} catch (_) {}
if (!ms || ms.length < 500) {
  try { ms = $('02F – FALLBACK MANUSKRIPT NORMALISIEREN').first().json.response || ''; } catch (_) {}
}
if (!ms) throw new Error('Kein Manuskript für Lektorat vorhanden.');

const modus = String(s.qualitaetsmodus || 'hoch').toLowerCase();
const schnell = s.schnellmodus === true;
let maxTok = Number(s.max_tokens_lektorat) || 24000;
if (schnell) maxTok = Math.min(maxTok, 15000);

const maxIn = modus === 'maximal' ? 52000 : 45000;
const msForPrompt = ms.length > maxIn
  ? ms.slice(0, maxIn) + '\n\n[... Text für Prompt-Limit gekürzt ...]'
  : ms;

const qualityExtra = {
  standard: `- Rechtschreibung, Grammatik und Zeichensetzung korrigieren
- Offensichtliche Brüche und Markdown-Reste entfernen`,
  hoch: `- Rechtschreibung, Grammatik, Zeichensetzung und Stil glätten
- Doppelte Sätze und Wiederholungen streichen
- Namen, Begriffe und Zeitformen vereinheitlichen
- Abgebrochene oder unklare Sätze reparieren
- Markdown-Artefakte vollständig entfernen
- Inhalt, Kapitelreihenfolge und Aussage nicht verändern`,
  maximal: `- Vollständige Schlusskorrektur auf Verlagniveau
- Stil, Rhythmus und Lesbarkeit spürbar verbessern, ohne den Inhalt zu ändern
- Absolute Konsistenz bei Namen, Begriffen, Anrede und Tempus
- Alle Doppelungen, Brüche und Formatierungsreste entfernen
- Schwache Übergänge zwischen Absätzen glätten
- Keine neuen Fakten, keine neuen Kapitel, keine Sinnänderung`
}[modus] || '';

const prompt = `Du bist erfahrener Lektor und Schlusskorrektor für deutschsprachige Sachbücher.

Erstelle die endgültige, veröffentlichungsreife Fassung.

REGELN:
1. Handlung, Struktur, Kapitel und Kernaussage bleiben erhalten.
2. Keine neuen Inhalte, Fakten oder Szenen erfinden.
3. Titel und Autorenhinweis beibehalten.
4. Gib AUSSCHLIESSLICH den fertigen Buchtext zurück (keine Erklärung, kein Bericht).
${qualityExtra}

MANUSKRIPT:
${msForPrompt}`;

return [{
  json: {
    originalManuscript: ms,
    originalLength: ms.length,
    qualitaetsmodus: modus,
    requestBody: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: {
        maxOutputTokens: maxTok,
        temperature: 0.2
      }
    }
  }
}];

const asText = (v) => {
  if (typeof v === 'string') return v.trim();
  if (Array.isArray(v)) return v.map(asText).filter(Boolean).join('\n').trim();
  if (v && typeof v === 'object') return asText(v.text ?? v.content ?? '');
  return '';
};
const fixed = asText($json?.candidates?.[0]?.content?.parts) || '';
const body = $('03 – LEKTORAT + ENDFASSUNG BODY').first().json;
const original = body.originalManuscript || '';
let response = (fixed.length >= 800 ? fixed : original)
  .replace(/^\s*```(?:markdown|text)?\s*/i, '')
  .replace(/\s*```\s*$/, '')
  .trim();
if (!response) throw new Error('Endfassung ist leer.');

// --- Leichte Qualitätsprüfung (0 €) ---
const markers = [];
const warnings = [];
const lower = response.toLowerCase();

if (/\b\[fakt prüfen\]/i.test(response)) markers.push('[FAKT PRÜFEN]');
if (/\bTODO\b|\bFIXME\b|\bXXX\b/i.test(response)) markers.push('TODO/FIXME');
if (/```/.test(response)) warnings.push('Markdown-Codeblöcke noch vorhanden');
if ((response.match(/^#{1,3}\s/gm) || []).length < 4) warnings.push('Weniger als 4 erkennbare Überschriften');
if (response.length < 3000) warnings.push('Text ungewöhnlich kurz');
// abgeschnitten wirkende Enden
if (/\b(der|die|das|und|oder|ein|eine)\s*$/i.test(response.slice(-80))) {
  warnings.push('Möglicherweise abgeschnittener Schlusssatz');
}

const needsAttention = markers.length > 0 || warnings.length > 0;

return [{
  json: {
    ok: true,
    response,
    lektoratFallbackVerwendet: fixed.length < 800,
    rechtschreibungStatus: fixed.length >= 800
      ? 'Lektorat + Korrektur angewendet'
      : 'Originalmanuskript (Lektorat-Fallback)',
    charCount: response.length,
    qualityMarkers: markers,
    qualityWarnings: warnings,
    needsQualityAttention: needsAttention
  }
}];

const s = $('00 – EINSTELLUNGEN').first().json;
const end = $('03B – ENDFASSUNG NORMALISIEREN').first().json || {};
const text = String(end.response || '');
