return [{json:{...$('07 – INNEN HTML BAUEN').first().json,pdfValid:true},binary:{data:pdf}}];

const s = $('00 – EINSTELLUNGEN').first().json;
const p = $('05C – FEHLERSUCHE AUSWERTEN').first().json;

const title = String(p.titel || 'Buchprojekt');
const slug = title.normalize('NFKD')
  .replace(/[^a-zA-Z0-9äöüÄÖÜß]+/g, '_')
  .replace(/^_+|_+$/g, '')
  .slice(0, 80) || 'Buchprojekt';

const safeNode = (name) => {
  try {
    const node = $(name).first();
    return node ? node.json : null;
  } catch {
    return null;
  }
};

const research = safeNode('01B – RECHERCHE PRÜFEN');
const sourceAnalysisBody = safeNode('01G – NOTEBOOKLM QUELLENANALYSE BODY');
const manuscriptCheck = safeNode('03 – LEKTORAT BODY');
const spelling = safeNode('03B – ENDFASSUNG NORMALISIEREN');
const endfassungBody = safeNode('04 – ENDFASSUNG BODY');
const coverCheck = safeNode('06E2 – COVER PDF PRÜFEN');
const interiorCheck = safeNode('07A2 – INNEN PDF PRÜFEN');
const ebookCheck = safeNode('06I – EBOOK COVER PRÜFEN');
const finalProduct = safeNode('08 – FERTIGES PRODUKT');

const warnings = [];
const errors = [];

if (!research) warnings.push('Quellenanalyse konnte im Protokoll nicht gelesen werden.');
if (manuscriptCheck?.manuscriptFallbackUsed === true) {
  warnings.push('Beide Schreibmodelle lieferten kein verwertbares Manuskript. Eine technische Notfall-Zwischenfassung wurde erzeugt.');
}
if (sourceAnalysisBody?.researchFallbackUsed === true) {
  warnings.push('Die erste Recherche und ihr API-Fallback lieferten keine verwertbare Antwort. Die Quellenanalyse wurde direkt aus dem Buchauftrag aufgebaut.');
}
if (!spelling) warnings.push('Rechtschreibprüfung konnte im Protokoll nicht gelesen werden.');
if (endfassungBody?.lektoratFallbackVerwendet === true) {
  warnings.push('Beide externen Lektoratsprüfer lieferten keinen Bericht. Die Endfassung verwendete das automatische Notfall-Selbstlektorat.');
}
if (!coverCheck) warnings.push('Cover-PDF-Prüfung konnte im Protokoll nicht gelesen werden.');
if (!interiorCheck) warnings.push('Innen-PDF-Prüfung konnte im Protokoll nicht gelesen werden.');
if (!ebookCheck) warnings.push('E-Book-Cover-Prüfung konnte im Protokoll nicht gelesen werden.');

if (research?.notebookAnalyseStatus?.toLowerCase().includes('fallback')) {
  warnings.push('Die Recherche verwendete einen Fallback.');
}
if (spelling?.rechtschreibungStatus &&
    !String(spelling.rechtschreibungStatus).toLowerCase().includes('bestanden')) {
  warnings.push(`Rechtschreibung: ${spelling.rechtschreibungStatus}`);
}
if (p.qualitaetsfreigabe !== true) {
  warnings.push('Die unabhängige Fehleranalyse hat keine vollständige Freigabe erteilt.');
}
if (coverCheck?.pdfValid === false || coverCheck?.valid === false) {
  errors.push('Cover-PDF ist nicht gültig.');
}
if (interiorCheck?.pdfValid === false || interiorCheck?.valid === false) {
  errors.push('Innen-PDF ist nicht gültig.');
}

const audit = p.qualitaetsaudit || {};
const severe = Array.isArray(audit.schwere_fehler) ? audit.schwere_fehler : [];
const auditWarnings = Array.isArray(audit.warnungen) ? audit.warnungen : [];
const markers = Array.isArray(audit.gefundene_marker) ? audit.gefundene_marker : [];

errors.push(...severe.map(x => `Qualitätsprüfung: ${x}`));
warnings.push(...auditWarnings.map(x => `Qualitätswarnung: ${x}`));
warnings.push(...markers.map(x => `Offener Marker: ${x}`));

const steps = [
  {
    schritt: 'Auftrag und Einstellungen',
    status: s.buchauftrag ? 'OK' : 'WARNUNG',
    details: s.buchauftrag ? 'Buchauftrag vorhanden.' : 'Buchauftrag fehlt oder ist leer.'
  },
  {
    schritt: 'OpenCode-Recherche',
    status: 'AUSGEFÜHRT',
    details: 'Erstrecherche wurde ausgeführt; bei Fehlern greift der bestehende Fallback.'
  },
  {
    schritt: 'NotebookLM-ähnliche Quellenanalyse',
    status: research?.notebookAnalyseStatus || 'UNBEKANNT',
    details: research?.sources?.length
      ? `${research.sources.length} Quellen im Grounding-Bericht.`
      : 'Keine oder nicht auslesbare Quellenliste.'
  },
  {
    schritt: 'Manuskript',
    status: safeNode('02C – MANUSKRIPT OK?') ? 'AUSGEFÜHRT' : 'NICHT LESBAR',
    details: 'Manuskriptstufe und Fallback-Pfad geprüft.'
  },
  {
    schritt: 'Lektorat und finale Fassung',
    status: safeNode('04 – FINALE VERSION') ? 'AUSGEFÜHRT' : 'NICHT LESBAR',
    details: 'Lektorat, finale Fassung und vorhandene Korrekturstufen.'
  },
  {
    schritt: 'Rechtschreibprüfung',
    status: spelling?.rechtschreibungStatus || 'UNBEKANNT',
    details: spelling?.rechtschreibungDetails || ''
  },
  {
    schritt: 'Unabhängige Fehlersuche',
    status: p.qualitaetsstatus || 'UNBEKANNT',
    details: audit.zusammenfassung || ''
  },
  {
    schritt: 'Cover-Erstellung',
    status: coverCheck?.pdfValid === false || coverCheck?.valid === false ? 'FEHLER' : 'OK',
    details: 'Logo klein oberhalb des Barcode-Bereichs positioniert.'
  },
  {
    schritt: 'E-Book-Cover',
    status: ebookCheck?.ebookCoverValid === true ? 'OK' : 'WARNUNG',
    details: ebookCheck?.ebookCoverValid === true
      ? `${ebookCheck.ebookCoverDimensions}, JPEG, ${ebookCheck.ebookCoverBytes} Byte.`
      : 'E-Book-Cover konnte nicht vollständig geprüft werden.'
  },
  {
    schritt: 'Innen-PDF',
    status: interiorCheck?.pdfValid === false || interiorCheck?.valid === false ? 'FEHLER' : 'OK',
    details: 'Innen-PDF wurde mit Gotenberg erzeugt und geprüft.'
  },
  {
    schritt: 'Abschluss',
    status: errors.length ? 'FEHLER' : warnings.length ? 'MIT WARNUNGEN' : 'OK',
    details: finalProduct?.hinweis || 'Abschlussdaten wurden erstellt.'
  }
];

const report = {
  workflowVersion: '7.5',
  modellkette: s.modellkette,
  copilotVerwendet: false,
  erstelltAm: new Date().toISOString(),
  titel: title,
  gesamtergebnis: errors.length ? 'FEHLER' : warnings.length ? 'MIT WARNUNGEN' : 'OK',
  zusammenfassung: {
    fehlerAnzahl: errors.length,
    warnungenAnzahl: warnings.length,
    qualitaetsfreigabe: p.qualitaetsfreigabe === true
  },
  fehler: errors,
  warnungen: warnings,
  schritte: steps,
  dateien: {
    coverPdf: `${slug}_COVER.pdf`,
    ebookCover: `${slug}_EBOOK_COVER.jpg`,
    innenPdf: `${slug}_INNEN.pdf`,
    rechercheUndFehlerbericht: `${slug}_RECHERCHE_UND_FEHLERBERICHT.json`,
    ablaufprotokoll: `${slug}_ABLAUFPROTOKOLL.json`
  },
  hinweis: 'Das Ablaufprotokoll zeigt technische und inhaltliche Auffälligkeiten. Die endgültige Prüfung im KDP Previewer bleibt notwendig.'
};

const data = await this.helpers.prepareBinaryData(
  Buffer.from(JSON.stringify(report, null, 2), 'utf8'),
  `${slug}_ABLAUFPROTOKOLL.json`,
  'application/json'
);

return [{
  json: {
    ...p,
    ablaufprotokollStatus: report.gesamtergebnis,
    ablaufprotokollFehler: errors.length,
    ablaufprotokollWarnungen: warnings.length,
    ablaufprotokollPath: `/buch/${slug}_ABLAUFPROTOKOLL.json`
  },
  binary: { data }
}];

const p = $('05C – FEHLERSUCHE AUSWERTEN').first().json;
