return [{
  json: {
    status: log.ablaufprotokollStatus === 'FEHLER' ? 'FERTIG MIT FEHLERN' :
      log.ablaufprotokollStatus === 'MIT WARNUNGEN' ? 'FERTIG MIT WARNUNGEN' : 'FERTIG',
    titel: title,
    modellkette: $('00 – EINSTELLUNGEN').first().json.modellkette,
    copilot: 'nicht eingebaut',
    ordner: 'C:\\Users\\NUTZER\\Desktop\\Die Firma\\Buch Ergebnisse',
    innen_pdf: `${slug}_INNEN.pdf`,
    cover_pdf: `${slug}_COVER.pdf`,
    ebook_cover: `${slug}_EBOOK_COVER.jpg`,
    ebook_cover_format: '1600 × 2560 px, JPEG',
    pruefbericht: `${slug}_RECHERCHE_UND_FEHLERBERICHT.json`,
    ablaufprotokoll: `${slug}_ABLAUFPROTOKOLL.json`,
    ablaufprotokoll_status: log.ablaufprotokollStatus,
    kleine_fehler_gefunden: log.ablaufprotokollFehler,
    warnungen_gefunden: log.ablaufprotokollWarnungen,
    quellenanalyse: $('01B – RECHERCHE PRÜFEN').first().json.notebookAnalyseStatus,
    rechtschreibung: $('03B – ENDFASSUNG NORMALISIEREN').first().json.rechtschreibungStatus,
    qualitaetsstatus: p.qualitaetsstatus,
    qualitaetsfreigabe: p.qualitaetsfreigabe,
    hinweis: log.ablaufprotokollStatus === 'OK'
      ? 'Alle Dateien wurden gespeichert. Das Ablaufprotokoll enthält keine erkannten Auffälligkeiten.'
      : 'Alle Dateien wurden gespeichert. Bitte zuerst das Ablaufprotokoll lesen; dort stehen Fehler und Warnungen nach Arbeitsschritt.'
  }
}];
